import{_ as e,o,c as r,a2 as a}from"./chunks/framework.CpZKh-tG.js";const p=JSON.parse('{"title":"Image-sourcing inventory — 2026-06-15","description":"","frontmatter":{},"headers":[],"relativePath":"provenance/image-sourcing-inventory.md","filePath":"provenance/image-sourcing-inventory.md"}'),i={name:"provenance/image-sourcing-inventory.md"};function s(d,t,n,c,l,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="image-sourcing-inventory-—-2026-06-15" tabindex="-1">Image-sourcing inventory — 2026-06-15 <a class="header-anchor" href="#image-sourcing-inventory-—-2026-06-15" aria-label="Permalink to &quot;Image-sourcing inventory — 2026-06-15&quot;">​</a></h1><p>Strict zero-image entries across every catalogued surface. Walks each entity through its primary image dir AND the runtime gallery loader&#39;s cross-surface fallback chain (<code>missions → mars-sites/moon-sites/fleet-galleries</code>, <code>mars-sites → missions/fleet-galleries</code>, etc.). Image-sharing across surfaces is preferred over duplication; this report respects that.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p><strong>13 catalogue entries → 7 unique physical entities</strong> (mission + fleet rows for the same asset count as one sourcing job).</p><table tabindex="0"><thead><tr><th>Surface</th><th>Catalogue entries</th><th>Of total</th></tr></thead><tbody><tr><td>missions</td><td>6</td><td>of 112</td></tr><tr><td>fleet</td><td>6</td><td>of 251</td></tr><tr><td>moon-sites</td><td>0</td><td>of 27</td></tr><tr><td>mars-sites</td><td>0</td><td>of 27</td></tr><tr><td>earth-objects</td><td>0</td><td>of 31</td></tr><tr><td>planets</td><td>1</td><td>of 9</td></tr><tr><td><strong>TOTAL</strong></td><td><strong>13</strong></td><td>of 457</td></tr></tbody></table><h2 id="the-7-unique-entities" tabindex="-1">The 7 unique entities <a class="header-anchor" href="#the-7-unique-entities" aria-label="Permalink to &quot;The 7 unique entities&quot;">​</a></h2><p>Sorted by sourcing difficulty (easiest first — anything that&#39;s already flown + returned data has public-domain imagery available).</p><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>mission id</th><th>fleet id</th><th>Status</th><th>Available imagery</th></tr></thead><tbody><tr><td>1</td><td><strong>Pluto</strong></td><td>—</td><td>—</td><td>Flown (planet, on /explore + planets.json)</td><td>New Horizons 2015 flyby imagery (NASA, public domain) — definitive Tombaugh Regio shot</td></tr><tr><td>2</td><td><strong>Hayabusa 1</strong> (JAXA)</td><td><code>hayabusa1</code></td><td><code>hayabusa</code></td><td>Completed 2010</td><td>Itokawa close-ups + spacecraft assembly photos (JAXA, public domain via NASA Photojournal)</td></tr><tr><td>3</td><td><strong>Solar Orbiter</strong> (ESA)</td><td><code>solar-orbiter</code></td><td><code>solar-orbiter</code></td><td>Active since 2020</td><td>ESA/NASA polar imaging, EUI close-up of the Sun, spacecraft renderings</td></tr><tr><td>4</td><td><strong>Parker Solar Probe</strong> (NASA)</td><td><code>parker-solar-probe</code></td><td><code>parker-solar-probe</code></td><td>Active since 2018</td><td>WISPR corona imagery from multiple perihelion passes (NASA/Johns Hopkins APL)</td></tr><tr><td>5</td><td><strong>Lucy</strong> (NASA)</td><td><code>lucy</code></td><td><code>lucy</code></td><td>Active; Dinkinesh flyby 2023</td><td>Dinkinesh asteroid binary photo (Nov 2023) + spacecraft photos + mission art</td></tr><tr><td>6</td><td><strong>Psyche</strong> (NASA)</td><td><code>psyche-mission</code></td><td><code>psyche-spacecraft</code></td><td>Active (cruise, arrival 2029)</td><td>Pre-launch integration + Hall-effect thruster firings + asteroid concept art</td></tr><tr><td>7</td><td><strong>Europa Clipper</strong> (NASA)</td><td><code>europa-clipper</code></td><td><code>europa-clipper</code></td><td>Active (cruise, arrival 2030)</td><td>Pre-launch assembly (Cape Canaveral 2024) + spacecraft renderings + Europa context</td></tr></tbody></table><h2 id="why-the-current-validate-hero-coverage-ts-doesn-t-catch-all-of-these" tabindex="-1">Why the current <code>validate-hero-coverage.ts</code> doesn&#39;t catch all of these <a class="header-anchor" href="#why-the-current-validate-hero-coverage-ts-doesn-t-catch-all-of-these" aria-label="Permalink to &quot;Why the current `validate-hero-coverage.ts` doesn&#39;t catch all of these&quot;">​</a></h2><p>The validator&#39;s MISSIONS_KNOWN_GAPS + FLEET_KNOWN_GAPS sets enumerate 12 of the 13 entries above; the 13th is <strong>Pluto</strong> on the <code>planets</code> surface, which the validator simply doesn&#39;t iterate. Phase 21 fix: add <code>planets</code> to the <code>SURFACES</code> list with its own <code>PLANETS_KNOWN_GAPS</code> set (Pluto if we&#39;re keeping it deferred; empty if we source it).</p><h2 id="sourcing-pattern-per-agents-md-§-image-pipeline" tabindex="-1">Sourcing pattern (per AGENTS.md § Image pipeline) <a class="header-anchor" href="#sourcing-pattern-per-agents-md-§-image-pipeline" aria-label="Permalink to &quot;Sourcing pattern (per AGENTS.md § Image pipeline)&quot;">​</a></h2><p>For each entity above:</p><ol><li><strong>Agency-first fetch</strong> via the existing pattern in <code>scripts/fetch-spacecraft-images.mjs</code> / <code>fetch-tier-*-images.mjs</code>. NASA APIs (<code>images.nasa.gov</code>, NASA Photojournal) for NASA + Johns Hopkins APL missions; ESA portal for Solar Orbiter; JAXA archive for Hayabusa 1.</li><li><strong>Wikimedia Commons fallback</strong> (<code>Special:FilePath</code> + search API) per the #5 Phase 4 pattern that sourced 57 of 58 previous gaps.</li><li><strong>Sidecar entry</strong> in the relevant manifest: <ul><li><code>static/data/mission-image-sources.json</code> for <code>&lt;id&gt;/&lt;slot&gt;</code> (no ext)</li><li><code>static/data/fleet-image-sources.json</code> for <code>&lt;id&gt;/&lt;slot&gt;.jpg</code></li><li><code>static/data/panel-image-sources.json</code> for <code>&lt;surface&gt;/&lt;id&gt;/&lt;slot&gt;</code> (planet panels)</li></ul></li><li><strong>Variant build</strong> — 1x1 only per the post-#5 image-pipeline v2 (4x3 / 16x9 are dead code).</li><li><strong>Hash + provenance</strong> — <code>npm run build:image-provenance</code> regenerates <code>image-provenance.json</code> (must be ✓ before commit).</li><li><strong>Verify</strong> — <code>npx tsx scripts/validate-hero-coverage.ts</code> must show zero unexpected gaps.</li></ol><h2 id="what-not-to-touch" tabindex="-1">What NOT to touch <a class="header-anchor" href="#what-not-to-touch" aria-label="Permalink to &quot;What NOT to touch&quot;">​</a></h2><p>Per Marko&#39;s directive 2026-06-15: <strong>incremental, no old images modified</strong>. Sourcing for the 7 entities above is purely additive — new files in their existing-but-empty directories. No re-sourcing of any entity that already has imagery.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><ul><li><strong>Phase 21</strong> (this report): inventory + validator surface for <code>planets</code>.</li><li><strong>Phase 22+</strong> (deferred): per-entity sourcing PRs, one entity per commit per the established pattern.</li></ul><hr><p><em>image-sourcing-inventory.md · Orrery · 2026-06-15 · supersedes the implicit &quot;known-gaps&quot; assumption in <code>validate-hero-coverage.ts</code></em></p>',19)])])}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
